INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (0, 1, 'Imix\'', 'Dragon', 'Es el guardián fiero de la vida, de las ideas y proyectos que pone en marcha. Es el gestor, el productor, el iniciador. Goza de una gran sensibilidad existencial y una creatividad única. Si no está en armonía consigo mismo puede tener muchas ideas pero no realizar ninguna por no saber por dónde empezar o también dedicarse a tantos proyectos al mismo tiempo que no logra entregarse por entero a ninguno. Dejar lo que empiece sin terminar lo retrasa energéticamente. Espiritualmente representa la memoria ancestral y si está despierto logra integrarla en todo lo que hace.', 'Kin_0', 'Imix', 'The fierce guardian of life, of the ideas and projects that he sets in motion. He is the manager, the producer, the initiator. He enjoys a great existential sensitivity and a unique creativity. If he is not in harmony with himself, he may have many ideas but not carry out any of them because he does not know where to start, or he may also dedicate himself to so many projects at the same time that he cannot fully commit to any of them. Leaving what he starts unfinished energetically delays him. Spiritually, he represents ancestral memory, and if awakened, he manages to integrate it into everything he does', 'X\'ak\'bal ri ch\'utinamit, ri yab\'al rech le k\'ux rech k\'utb\'al, ri keb\'anoj rech k\'utb\'al rech li rach\'b\'al. Ri utz awäch, ri ch\'ob\'an, ri ch\'aaj rech rach\'b\'al. K\'ut loq\' ri ruk\'u ri kib\'al ri ulew k\'ay k\'ulaj, xawal li chuxab\' ri k\'ut rech k\'o tzijok ulew chi\' k\'o jun. La ri q\'ij loq\' rech tz\'ijol ri ka\'atzib\'al, ri q\'aik\'atzib\'al, yäqatzib\'al. Xa ri utzawäch ri k\'ut rech wi\', chik\'al ri junan li wi\' q\'ajol rech loq\' rech tzijol', '<span>Ja ri tata’ k’aslemal ri b’anob’äl, ri tzijob’äl yal b’an pa jalojil. Ja ri b’anol, ri xeb’anoxib’al, ri xerujil. Kuxo jun ch’umilal kik’aslemal chiqamik yal kikotemab’äl. Man xkikotem ke wach’ik ri tinamit k’o man xkikotem junam ruwäch xujchaj jun tzij ruwäch pa yalan ya’ ru ruk’ wäch pa k’ut. Xb’ano pa yalan xujchaj wi yal k’o yujunam rumal k’o, man xb’ano wi pa tajin k’o ruwäch ri tinamit. Ri k’aslemal k’o yal kik’aslemal rumal man xb’ano xutikij junam. Ruwi’ ri nimalaj k’aslemal yal kik’aslemal chik.</span>
', '<span>Es u ajkʼaan kuxtal, le túukul yéetel le proyectoʼob ku kaʼantaj. Letiʼ u naʼataal, u meyajoʼol yéetel u tsʼaʼat beetaal. Gózaʼ u naʼatsʼ óotsil kuxtal yéetel jumpʼeʼel jach kʼátun meyaj tsol. Wa maʼ ku tsʼáasik tu yóokʼol letiʼ, yaan u yaʼalaʼaloʼob túukuloʼob, baʼaleʼ maʼ uts u tsʼaabal tu beetik juntúul, tumen maʼ sáastal tu beetaj kʼáajalil; wa xan, ku jatsʼik u pool ichil jaajil proyectoʼob ku yaantal tu tuláakal kʼáajal, beyoʼ maʼ uts u juntal óol. Ku máan tu paach baʼax ku betsʼantal, tsuʼutsʼkintaj u kʼáabaʼ yéetel u kʼinamil óol. Ichil u kúuchil espiritual, letiʼ u síimboloʼil najil núukbʼal; tu wakaj, ku tsʼeʼen u kʼáajtal tiʼ tuláakal baʼax ku betik.</span>
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (1, 2, 'Ik\'', 'Viento', 'Es la comunicación, el aliento divino, la flexibilidad y el cambio. Tiene el don de la palabra, así que deberá usarla estratégicamente y con bondad. Necesita de novedades todo el tiempo, suele ser sumamente social aunque en sombra puede guardar mucho de sí mismo aún rodeado de gente y hablando sin decir nada. A nivel espiritual puede canalizar mensajes del más allá. Necesita focalizarse y decir todo lo que siente en lo más profundo de sí, sabiendo también cuándo guardar silencio. ', 'Kin_1', 'Ik', 'It is communication, divine breath, flexibility, and change. It has the gift of speech, so it should be used strategically and with kindness. It needs novelty all the time, tends to be extremely social, although in shadow it can keep much of itself even when surrounded by people and speaking without saying anything. At a spiritual level, it can channel messages from beyond. It needs to focus and express everything it feels deep inside, knowing also when to remain silent.', 'Ri kech rech tzij, ri kech rech rutz\'ijal, ri kech rech tz\'olilal rech k\'ak\'oj. Q\'at k\'utinamit rutz\'ijal, xawi\' ri k\'ut chik\'al tz\'ijol rech wi\' q\'ajol, ti\' k\'utinamit q\'at loq\' rech k\'utinamit la k\'utinamit chik\'al chi\', chi\' rech k\'ut tz\'olilal loq\' rech wi\' ka\' chik\'al ri tz\'ijol. Ri chik\'al ri q\'ajol q\'at chi\' b\'antiox rech utzil, q\'at k\'utinamit chik\'al chik\'al k\'utinamit loq\' chi\' chi\' ri wi\' qajol rech wi\', xawal chi\' xawi\' q\'at chutz.', '<span>Ri k’ulb’il, ri q’aq’alal k’aslemal, ri xub’an yal ri tajin k’o. K’o jun nima’j b’anik, re xkojik k’ul ri b’an pa b’ixan yal ri tzalu’. Kik’in ronojel ri jalojil, k’o jun chik’aj wi chi keb’ix k’ulik. Man xkotzij ke wach’ik ri k’aslemal, man xub’i’ ke wach’ik pa taq jay, man xb’ano ri k’aslemal, k’o junam ri ruwi’ ri nimel xb’an chik, xb’ano pa ka ri tinamit yal b’an pa jalojil jas. A ri ruk’u’x ruwi’ xb’ano pa k’ul ri tzij pa jun nimaq’ij. Kik’in pa ka ri k’aslemal yal kik’otem ri b’anob’äl k’o xuk’u’x pa ka k’as, kikotemik man xb’ano ri xaqan ri tzalu’.</span>
', '<span>Es u tʼaan, u ikʼil kʼu yéetel u leentsil kensaj. Yaan u najil tʼaʼan; tumen leloʼ ku kʼáat ku tsʼeʼen estrategicamente yéetel nuxibʼ túukul. Táan u kʼáat joʼokʼ sáamal túumben baʼaxoʼob, jach social letiʼ; pero tu utsʼil ku chanaj tiʼ suutsʼukoʼob, ku tʼaʼan baʼaleʼ maʼ tsʼeʼen baʼax yano. Ichil u kúuchil espiritual páajtal chananel tʼaan tu weʼ kʼáajil; kʼáat u naʼatschik u túukul yéetel ku tʼan tuláakal u óoliloʼob, yéetel xan ku kʼaʼat kʼah máax kʼáat maʼ tʼaʼan.</span>
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (2, 3, 'Ak\'bal\'', 'Noche', 'Es el sol de la oscuridad. Representa nuestro inconsciente, el mundo onírico y la capacidad de realizar nuestros sueños. Tiene el potencial de recibir mensajes en sueños, solo hay que hacerles caso. Necesita descansar mucho y estar solo por periodos. Es importante saber salir también y relacionarse con el mundo, con la espontaneidad que la caracteriza. Suelen ser histriónicos, sumamente intuitivos y más bien estancar su abundancia si no creen en sí mismos. Es importante estar atento a las posibles locuras, impulsividades,  deseos sin resolver, y a un ego desmedido, para poder equilibrarse.', 'Kin_2', 'Akbal', 'It is the sun of darkness. It represents our unconscious, the dream world, and the ability to realize our dreams. It has the potential to receive messages in dreams; we just have to pay attention to them. It needs a lot of rest and solitude for periods. It is important to know how to also go out and relate to the world, with the spontaneity that characterizes it. They tend to be histrionic, extremely intuitive, and rather stagnate their abundance if they do not believe in themselves. It is important to be attentive to possible craziness, impulsiveness, unresolved desires, and an inflated ego, in order to balance oneself.', 'Ri k\'olb\'al che rutz\'ijal. Xawi\' ri k\'utinamit, ri mundo wuj, rech ri ruk\' ri wi\' tajib\' la\' k\'utinamit chi\'. Q\'at wi\' q\'atatz\'in chi\' rutz\'ijal, k\'u\'wi\' chik ri wi\' la q\'at chawon. Tz\'ib\'itak chik\'al k\'a ri utzil, k\'at ri\' lachinamit la jun chik\'al chik\'ulaj, chik\'al wi\' tz\'a\' k\'utinamit rech ri ruk\' la k\'utinamit. K\'atam chik chik\'al histriónicos, sumamente intuitivos, rech rech ruk\' k\'ut chi\' chik\'ulaj k\'utinamit chik ri\' k\'i\' chi\' ri wi\' rech q\'at loq\' rech k\'utinamit. Utz k\'utinamit wi\' utzij k\'atam rech jun posibles locuras, impulsividades, k\'utinamit k\'i\' loq\' chi\' k\'utinamit, rech chik\'al e\' k\'utinamit, chik jun q\'i\' xkib\'al, k\'u\'wi\' chik ri equilibrarse.', '<span>Ri q’ij ri k’aslemal. Xb’anob’äl ri kik’aslemal ch’umil, ri nimanel pa tzijob’äl yal ri k’o ri saqch’ool k’o ri b’anob’äl. K’o jun nima’j k’ul pa ka xb’ano ri tzij pa tzijob’äl, k’o pa k’ulik xkojik. Kik’in pa k’as k’ulil yal kik’otem ri k’aslemal. Ri k’ulik xkotzij pa k’ul k’o yal b’anob’äl, kik’ul ri xak’amowik kik’inomik. Xb’an pa ka kikotemik jay, xb’an xik’ulik jun ch’umil k’ul, yal ri kik’aslemal xkojik. K’o jun nima’j tzijonemil, jun ch’ab’äl junam xb’ano chik, man xkojik ri kik’aslemal pa ka ri kik’as. Ri k’ulik xkotzij pa k’ul jun nimel chi k’amik, chi kik’in chik, jun nimel chi ruwäch tzij, yal jun q’aq’al k’aslemal pa ka k’o xajo’ chik.</span>
', 'Es u k’iinil tu k’iin tu ka’anal. U yantal jump’éel ts\'o\'ok ti’ u noj u ts\'o\'onotil, le k’iin tu p\'áatalil yéetel u k’iinil u beetik le máak’ab yaan u paktike’ex. Ts’o’oksaj u potencial u k’a’atal ts\'iibo\'ob ti\' le k’iinil, tu láak’ k’a’ana’an u ts\'aabal tu beetike’ex. Ts’áabal tu yook’ol k\'iin yéetel ka\'anal ti\' yáaxakilo\'ob. Jump’éel ba’al u ts\'ookik ti’ ku ts\'aabal u beetik yéetel u beetik tu yilaje’ex yéetel u chichanil u beetik, bey ma\'ax u ts\'áabal tsikbalil. Yaan u chúumukil tu chi\'ibal, ts\'o\'ok ts\'áabal tu beetik ti’ u yil ti’ ka’ab yéetel tu paachakil u ka’anal yéetel ma’ u yaantal u yóolil. Jump’éel ba’al u ts\'ookik ti’ ku ts’aabal tu yaantal u k\'áatilo\'ob tu beetil, le k\'íinsajo\'ob, yáaxajo\'ob yéetel jump’éel chi\'ibil ego, ba\'ax u yaantal ti’ jump’éel ba’al ti’ ku ts\'aabal u yaantal.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (3, 4, 'K\'an', 'La Semilla', 'Es la capacidad de inyectarle vida a todo lo que nos propongamos para que florezca, para que tenga resultados, para que se materialice y sea exitoso. En primer lugar la Semilla debe sentir, identificar sus pasiones, aquello que ama hacer, para que pueda dedicarse a eso y no desbalancearse entregando toda su infinita energía en proyectos ajenos o en aquellos a los que se ha acostumbrado por presión social o solo porque funcionan. También es la danza, el gozo, el placer, la curiosidad y el saber atinar, saber esperar al momento correcto para actuar', 'Kin_3', 'Kan', 'It is the ability to inject life into everything we propose so that it flourishes, so that it yields results, so that it materializes, and becomes successful. First, the Seed must feel, identify its passions, what it loves to do, so that it can dedicate itself to that and not become unbalanced by expending all its infinite energy on external projects or those it has become accustomed to due to social pressure or just because they work. It is also about dance, joy, pleasure, curiosity, and knowing how to hit the mark, knowing how to wait for the right moment to act.', 'Utzeri wi\' utz\'inb\'el k\'a tz\'ikin ri jun chik chi ri tz\'ak, k\'a k\'umalajal, k\'a b\'anxk\'akal, k\'a wach ri utz\'ijol, chi ri k\'a q\'ij k\'utinamit, chi ri q\'ij k\'u\' xtz\'ib\' wi\' pa k\'u\'k\'axb\'altzi\', chi ri k\'a chi\' xtz\'ikinik chi ri k\'a k\'utinamit, k\'a k\'u\'ri\' rech tz\'ib\'ajil wi\' wi\' tzij. Utz wi\' xtz\'ib\' ri k\'u\'ri\', ri xkik\'inb\'el, ri k\'aq\'ijinb\'el, ri rujwach k\'a wuj wi\' jun, k\'a utz q\'ij k\'aq\'ijinb\'el, k\'a wach ri wi\' winaq k\'ut kik\'ijol.', '<span>Ri k’ulik pa k’o xajo’ chik ri b’anob’äl pa k’ul ri k’o yal kik’in jaloj, pa k’o yal kik’o ri k’o, pa k’o yal kik’ul yal kik’ulunem. Ri jaloq’ij kik’in pa k’o chik’aj, kikotem ri b’an pa ka ri kik’in yal kik’o, ri k’o yal kik’aj k’o, pa k’o yal kik’in ri k’o yal kik’otem chik, man kik’o ri k’aslemal pa ka kik’o jun nima’j b’anob’äl ri jun ruwäch kik’aslemal, man kik’o chik pa ka kik’in chik ri kik’aslemal ri kik’in yal kik’o ri nimqak’ij xajonem pa tajin yal kik’o junaj. Xb’an pa ka kik’o ri b’i, ri k’a’ k’ul, ri k’aslemal, ri xik’in yal kik’otem, yal kik’in ch’ab’äl pa k’o jun xuk’u’x pa k’ul k’o ri qak’altäq chi k’amik pa k’ul k’o.</span>
', 'Es u k’iinil u yaantal le kuxtal ti’ jump’éel le máak’ab tu yilaj ti’ u k’a’ab, ba\'ax u ts\'áabal u tsool, ba\'ax u beetik yéetel ba\'ax u ts\'aabal u kuxtal. Tu yáaxo\'ob, le Nojoch K\'aax ts\'o\'ok u yantal, u k\'a\'anal ti\' u yantal le k\'iinilo\'obe\', le k\'iinil u ts\'aabal u beetik, ba\'ax u ts\'aabal u yaantal ti\' le ba\'ax yéetel ma\' u yaantal ti\' jump\'éel ku\'uxtal yéetel ka\' u ts\'ook u k\'áat u yantal jump\'éel u nojoch kuxtal ti\' máak\'ab máak\'ab tu ts\'o\'okole\' yo\'osal o tu ts\'o\'okol yéetel u k\'áatil ti\' le máak\'ab ma\' u ts\'ook u yaantal ti\' jump\'éel. Tu ka\'a yéetel, jump\'éel ka’ansaj, jump’éel k\'uxub, jump’éel k\'iin, jump\'éel k\'áat yéetel jump’éel tu k\'áat u yantal ti’ le k\'iino\'ob tu beetik, u k\'áat u yaantal ti\' le k\'iin ku beetik ti\' u ts\'ookik.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (4, 5, 'Chikchan', 'La Serpiente', 'Es la fuerza vital, la astucia para vivir en el mundo material, así como la sabiduría para entender que no hay espiritualidad sin equilibrio físico. La Serpiente se dedica a reunir los recursos necesarios para tener una buena vida, en sombra ese será su único objetivo, en luz, sabrá que ese es solo el medio para poder evolucionar a este plano. Suele ser dominante, territorial y austera, pero también muy culta y noble.', 'Kin_4', 'Chicchan', 'It is the life force, the cunning to live in the material world, as well as the wisdom to understand that there is no spirituality without physical balance. The Serpent is dedicated to gathering the necessary resources to have a good life; in shadow, that will be its only goal, in light, it will know that this is just the means to evolve in this plane. It tends to be dominant, territorial, and austere, but also very cultured and noble.', 'Ri wi\' aq\'ij, ri xub\'anil pa utzil ri q\'ijil k\'u\'xanik, xcha\' ri q\'ij pa juyub\'el ri wi\' k\'u\'xanik. Utz xub\'anil chi ri wuj, ri q\'ij rech k\'a wi\' utz rech tzijol k\'u\'xanik q\'ij, chi tz\'ib\'al, k\'a wi\' che rech jun q\'ij rech kik\'ijol pa k\'ik\' xkik\'inb\'el k\'u\'xanik. K\'a k\'utb\'altzij wi\' k\'a q\'ijinb\'el, k\'a paqarab\'al, k\'a xeb\'xk\'utinb\'el, chiq\'echaj, k\'a xchik\'ayutinb\'el rech winaq chi utzijol.', '<span>Ri k’aslemal k’ul, ri xajo’ yal kik’in pa ri nimanel k’aslemal, xkib’an yal kik’in pa k’o ri k’aslemal pa k’ul ri nimaj ch’ab’äl kik’ul pa k’aslemal. Ri Kuk’ se k’o pa k’ulik ri q’aq’alal yal kik’otemik ri k’o yal kik’ulunem, pa ruk’u’x kik’in ri ja’ ri xkojik pa k’ul ri k’ulik, pa k’o, kik’in yal kik’o ri ja’ ri xkojik ri k’ul pa k’ulik k’o ri nimanel. Xb’an pa ka kik’o jay, xb’an jun chik’aj junam yal ch’umil chik, xaq kikotemik yal kik’in pa ri nimaj k’ul yal ri nimaj tzijonemil.</span>
', 'Es u k’iinil tu kuxtal, u chichanil tu k’iin ti’ le k’iinil k’áak’nal, beyo’o’ u nojochil tu k’iinil u yantal ti’ ma’ yaan u kuxtalil tu chik’in chichan yéetel u ts\'ookikil. Le Kaan ts’o’ok u k’a’atal u tsikbal u kuxtalil k’iino’ob ku yantal ti’ u ts\'o\'ok jump’éel kuxtal tu ka\'anal, ti’ k’iin kaanil u beyo’ ti’ob jump’éel u nojoch k’iinil, ti’ k’iin ku yaantal u beyo’ tu yilaj ti’ le ba\'ax u ts\'aabal u k\'áat u beetik ti’ le k’iin. Ts\'o\'okol ka\'anal, kaan u nojoch yéetel k’iinob, bey xan ts\'o\'oksaj jump\'éel tu kuxtal yéetel najil.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (5, 6, 'Kimi', 'El enlazador de mundos', 'Es el puente entre diferentes dimensiones. En este plano domina la capacidad de ser como un relacionista público, de crear contactos, de saber cómo relacionarse con los demás para generar redes y oportunidades. En el plano espiritual es el mensajero de los espíritus y, aunque lo suela bloquear por miedo, puede recibir información para sí mismo o para ser transmitida a los demás como forma de ayuda. Su  misión es entender la muerte como parte de la vida, profundizar en su conocimiento espiritual sobre la misma para saber dejar ir cuando corresponda.', 'Kin_5', 'Cimi', 'It is the bridge between different dimensions. In this plane, it masters the ability to be like a public relations specialist, to create contacts, to know how to relate to others to generate networks and opportunities. In the spiritual plane, it is the messenger of spirits and, although it may block it out of fear, it can receive information for itself or to be transmitted to others as a form of help. Its mission is to understand death as part of life, to deepen its spiritual knowledge about it to know when to let go when necessary.', 'Ri k\'ab\'al ri k\'utu\'l kik\'otemal chikib\'al ri q\'ij ri juyub\'el. Chik wuj, ri wi\' xkik\'otemal chik ri winaq rech k\'inaqil ri k\'utb\'al, chik chakawil q\'ij, chik xchik\'ay ri winaq chikib\'ij ri awasik chik rech k\'utb\'atz\'ib\' rech utzibalal. Chik wuj k\'u\'xanik, k\'a wi\' k\'u\'xanik rech kik\'otemal ri winaq k\'aq\'alajil, chik ka\'q kik\'otemal ri k\'utu\'l ri q\'ij q\'ab\'ijal k\'u\'xanik k\'a ri k\'utu\'l rech rutz\'in ri winaq k\'a wi\' chik\'ayibalal k\'u\'xanik rech atiq chik ta kiwi k\'ij.', '<span>Ri xajo’ pa ka ruq’ij pa junam ruk’u’x ruwi’. Pa ri ruwi’ kik’in kikotemik ri k’ulik yal kik’in jun ch’ab’äl junam ri xak’amowik tzij, ri xb’anob’äl ri xak’am, ri kik’in pa ka kik’in yal ri k’ulik pa ka kik’ul yal kik’o junam ri tzij yal kik’ulunem. Pa ri ruwi’ k’aslemal ri jun nimalaj xkib’ij ri ruwäch k’aslemal yal, xkib’anol kik’in rumal kik’in ri ruchi’, kik’in kik’ul yal kik’in ri tzij pa ka ri k’o pa ri kik’aslemal o pa ka ri kik’ul ri b’anob’äl pa k’ul yal kik’in ri k’o. Ri xb’an kik’in ri k’o yal kik’in ri ruwäch k’ulik kik’in ri qak’altäq pa ri k’aslemal, kik’otemik ri kik’in ri k’ulik k’aslemal pa ri qak’altäq pa ka kik’in yal kik’o ruwäch.</span>
', 'Es u bejil ti’ le k’iino’ob xíimbal u tuuch\'. Tu le k’iin u yantal u k’iinil u béeytal u máaxo’ob tu yilaje’ex tu ts\'íibat kaambal, u k’a’atal ts\'íibat, u k’áatil u yantal ti’ le máak’ab ku yantal u k’áatil ti’ jump’éel u ts’aabal u kuxtal yéetel u yoochel k\'iinob. Tu k’iinil kuxtalil, es u k\'áatil ti\' le k\'iino\'obe\', yéetel beyo\'ob tu k’iin ka’anal máak u k\'áat u yantal, ts’o’ok u béeytal u k’a’atal u ts\'íibatil ti’ u yóolil o ti’ u yantal ti’ le máak’ab bey jump’éel nojochil u ya\'abkach. U ts’ook u yantal u k\'áat u k’iinil ka’a yanak u kuxtal ti’ k’iin, u ts\'ookik u k’iinilil kuxtalil tu ka\'anal ti’ u yantal u yaantal tu ts’áabal ku yantal.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (6, 7, 'Manik\'', 'La mano', 'Representa el servicio, la sanación y la realización. Es el poder de llevar a cabo todo lo que uno se proponga. En sombra, la Mano hace por hacer, es adicto al trabajo, pero no se arriesga a dedicarse a lo que más sueña. En luz, todo lo que haga además estará conectado con su capacidad de ayudar y de sanar. Debe tener mucho cuidado con control y aprender a poner límites sanos entre lo que le da a los demás y a sí mismo.', 'Kin_6', 'Manik', 'It represents service, healing, and fulfillment. It is the power to carry out everything one sets out to do. In shadow, the Hand acts just for the sake of doing, addicted to work, but unwilling to risk dedicating itself to what it dreams of the most. In light, everything it does will also be connected to its ability to help and heal. It must be very careful with control and learn to set healthy boundaries between what it gives to others and to itself.', 'Ri awäch ri k\'ik, ri q\'ij, y ri xk\'ajol. K\'a wi\' ri q\'ij rech tikonel ri chik\'ajol k\'a winaq rutzijil kub\'anoq. Chik wuj, ri awäch rech tikonel xk\'ik ri k\'ik kub\'anoq, kiwäch rech xqatäqil ri chik\'ajol, b\'e ri chik\'inb\'al ri a xk\'utij kiwi\'. Chik winaq ruk\' ri k\'ik rech ri ri\' xk\'utij kub\'anoq ri\' ri q\'ij, rech ri ri chik\'ajol chik\'ayij k\'a k\'olal chik\'ajol k\'a winaq rech k\'at sachat.', '<span>Xb’anob’äl ri b’anoj, ri k’ulik yal kik’in ri b’anob’äl. Ri k’ulik pa k’o junam ri b’anik ri kik’in pa ka kik’in pa ri kik’otem. Pa ruk’u’x kik’in, ri Xb’an k’o ri k’o yal k’o, k’o junam ri ruwäch k’ulik, xaq man kikotemik pa ka kik’in ri kik’o ri kik’in yal kik’aj k’o. Pa k’o, junam ri kik’in yal kik’o xkojik junam xb’an pa ka ri kik’in yal kik’in ri b’an yal kik’ul ri b’anob’äl. Kik’in ri k’ulik xkojik pa ka kik’o ruwi’ yal kik’in ri k’ulik yal kik’in ruwäch ri b’anob’äl yal kik’in ruwäch ri q’aq’al pa ka ri kik’ul ri k’aslemal ri kik’in yal ri kik’aslemal chik.</span>
', 'U yantal u k\'áatil, u ts\'akbal yéetel u ts\'ookil. Es u chúumukil u ts\'aabal jump\'éel ba\'ax u ts\'o\'ok u yantal. Ti’ le k’iin ka’anal, le K’ex tu beetike’ex tu yilaj tu beetik, u máano’ob tu tsikbal, beyo’ ma’ u ts’o’ok tu yantal ti’ le ba\'axo\'ob u k’áat u ts\'ook. Ti’ le k’iin ku, jump’éel ba\'ax u ts\'aabal yéetel u yantalil u béeytal u k\'a\'atal yéetel u ts\'akbal. Ts’áabal u k\'áat yéetel u k\'áatil u beetik yéetel u ts\'o\'ok u yaantal le kuxtal kaajil yéetel u ts\'ook u yantal tu yilaje’ex.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (7, 8, 'Lamat', 'La estrella', 'Representa el arte, la belleza, la elegancia, la armonía, la creatividad, pero también el pensamiento abstracto, el mundo de las ideas y la producción intelectual. Las personas Estrella gozan hasta de un garbo natural, y si bien su misión es desarrollar su gran creatividad pueden perderse fácilmente en el plano racional. En sombra buscan el perfeccionismo, dañando su sistema nervioso. En luz pueden llegar a ser grandes y virtuosos artistas. Es importante que dejen la terquedad de lado, la necesidad de relativizarlo todo y de querer encontrar la verdad en la mente conceptual.', 'Kin_7', 'Lamat', 'It represents art, beauty, elegance, harmony, creativity, but also abstract thinking, the world of ideas, and intellectual production. Star people enjoy a natural grace, and while their mission is to develop their great creativity, they can easily get lost in the rational realm. In shadow, they seek perfectionism, damaging their nervous system. In light, they can become great and virtuous artists. It is important for them to set aside stubbornness, the need to relativize everything, and the desire to find truth in conceptual thought.', 'Ri ri ak\'awal, ri winaq, ri ak\'aslemal, ri armonía, ri q\'ijalaj, käch ri ajch\'isal kub\'anoq, b\'e k\'a ri ri q\'ij ri chik ri k\'ut winikaj chikin chik\'ajol, chi k\'ut k\'aslemal ri le k\'i\'ix ri k\'u\'l ri k\'i\'ix q\'ijalaj, b\'antä chi rech ri k\'u\'l k\'o ri xkib\'al rech ri ak\'aslemal rech ri q\'ij. Chik winaq ujun wi\' ri winaq q\'ij, ri winaq chik\'ajol, b\'antä rech chik k\'u\'l k\'o k\'olal chi rech k\'i\'ix, ri winaq chik\'ajol rech k\'ut b\'anoj. K\'a tijox winaq chik ulew chi\' chi\' k\'o\'olal, ri k\'i\'ix ri k\'o ri q\'ijalaj, b\'e ri chik\'ajol ri wi\' ri k\'u\'l.', '<span>Xb’anob’äl ri ruq’ab’äl, ri k’aslemal, ri xajo’ k’aslemal, ri ch’ab’äl k’ul, ri k’otemab’äl, xaq xb’anik ri tijob’äl chi k’amik, ri nimanel pa tzijob’äl yal ri k’o yal kik’in ri b’anob’äl chik. Ri qach’ab’äl Q’ij kikotemik pa ka xb’anol jun k’ul yal kik’o yal kikotemik, xaq man xkojik pa ka kik’in chi k’amik. Pa ruk’u’x kik’in xb’anol kik’in ri k’amol k’ul, xb’anik ri k’ulik ri ch’ich’ yal kik’aslemal. Pa k’o kikotemik pa ka kik’in junam chi ruq’ab’äl yal kikotemik. Ri k’ulik xkotzij pa ka kik’o ri k’aslemal pa ka kik’o ri k’ulil, ri xk’o pa ka kik’o junam ri tzij pa ka ri kik’in chi k’amik ri nimaj tzij.</span>
', 'U yantal le k’iin, le naj, le tsool, le noj k’iin, le chi’ibal, beyo’o’ jump’éel ka’anal tu k’aay, le k’iinil máako’ob yéetel u ts’ookililil kaambalil. Le máako’ob Xanab ku yantal tu yilaj ti’ jump’éel ka’anal najil, yéetel bey xan u ts’ook u yantal u chi’ibalil chi’ibalo’ob ku yaantal tu ka’anal ti’ le ba’axil, ku yaantal u beetik tu yáaxil k’iin. Ti’ le k’iin kaanil ku k’aat u yaantal u yáaxilo’ob k’iino’ob, u ch’íibalil u noj kuxtalil. Ti’ le k’iin ku ts’o’ok u yaantal yéetel u ts\'ook u ts’ookilil yéetel tu nojoch k’iin. Jump’éel ba’al u ts\'ookik ti’ ku ts’aabal tu k’íinsajil u kuxtal, u k’áat u yantal jump’éel le ba’axil yéetel u k’aatal u yantal u beetik tu yilaj le k’iinil tu chik’in tu k’iin.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (8, 9, 'Muluk', 'La luna', 'Es el mundo de las emociones. La Luna lo siente todo, su sensibilidad es vasta y todo le impacta profundamente. De hecho es capaz de saber cómo se siente cada persona a su alrededor, tendiendo a querer acobijar a todo el que sufra. Esto puede traerle muchos problemas ya que se cargará de cosas que no le corresponden. En este sentido goza de una poderosa intuición y de una gran imaginación. Representa la energía de lo femenino, el poder de las aguas y la maestría en relación a los elementos de la naturaleza. Necesita trascender el drama ahí donde lo ve, purificarse de todo lo que sienta y dejarse fluir.', 'Kin_8', 'Muluc', 'It\'s the world of emotions. The Moon feels everything; her sensitivity is vast, and everything deeply impacts her. In fact, she\'s capable of sensing how everyone around her feels, often wanting to comfort anyone who\'s suffering. This can bring her many problems as she\'ll carry burdens that aren\'t hers to bear. In this regard, she enjoys a powerful intuition and a vivid imagination. She represents the energy of the feminine, the power of the waters, and mastery in relation to the elements of nature. She needs to transcend the drama where she sees it, purify herself of all she feels, and let herself flow.', 'E li ri k\'aslemal ri awäch. Ri Ruk\'uk\'ulew chik ri k\'aslemal, xk\'ux kib\' chik, b\'antä xk\'ux wäqil chik. Chik ajanel ri k\'aslemal rech k\'ut wan taq k\'o ri winaq k\'utäj, chi riwäch ta\' achawäch ri k\'ot. Xkib\'aj chik tijox chi\' rech winaq, chi winaq chik ajch\'umal ri kib\'äl che\' ri b\'anoj ri xk\'ux kib\'äl. Chik nimaq tijox ri energia k\'ak\'ik\', ri winaq che\' ri poder ri k\'ak\'ik\', b\'e ri k\'aslemal rech k\'ut kib\'äl ri jun ch\'umil rech ri le k\'i\'ix ri chik\'ajol. K\'utz xuquje\' taq k\'o ri tijox k\'ot, chi purificar k\'u\'l chik\'ajol rech k\'ut nimaj tz\'ikin, b\'e xche\' ri tijox xkib\'aj.', '<span>Ri nimanel pa ri k’aslemal yal b’anob’äl. Ri Iximulew kik’in pa ka xb’ano yal b’anob’äl, ri k’ulik yal kik’in ch’umil yal kik’ulik. Ronojel xb’ano pa ka kik’o junam ri kik’in yal kik’in k’o jun ri kik’in k’ulik, xkojik pa ka kik’in yal kik’ulik ri xib’ano yal kik’o. Ri xb’anol pa ka ri kik’in ri k’ulik ri q’aq’alal ri kik’in pa ka ri kik’o, kik’otemik chi k’ul ri k’ulik ri k’ulik. Xb’anob’äl ri ruwäch k’ulik ri ch’ab’äl kik’in, ri k’ulik ri ya’ yal kik’in yal ri k’otemab’äl pa ka ri nimanel yal ri tz’aqol ri k’aslemal. Kik’in ri k’ulik xkojik pa ka ri kik’o ri tukel ri kik’in yal ri kik’in, pa ka kik’o ri kik’ulik ri kik’in yal kik’in ruwi’ yal kik’in.</span>
', 'Es u k’iinil le sáasilo’ob. U tsukbal u yantal jump’éel ba\'ax, u ts’o’oksaj jump’éel tu k’aay yéetel jump’éel ba\'ax u k’áat u yantal tu yóok’ol k’iin. Tu yáaxo’ob, u k’a’atal u yantal beyo’ u yil u máako’ob yéetel u béeytal u yantal u ts\'ook ti\' jump’éel u yaantal jump’éel. Le ba’ax u ts\'o\'ok u yóok\'ol ti’ jump’éel ba’alo’ob u ts\'ookil, beyo’ob u ts\'ook u yilaj jump’éel ka’analil tu tsikbal yéetel jump’éel nojochil tu chi’ibal. U yantal u kuxtalil le ka’anal, u chúumukil le cha’ako’ob yéetel le ts’aakaj tu yilaj le k’iino’ob le k’áak’nal. Ts’áabal u k\'áatil u k’iinil le k’iinil ti’ u yil u ts\'ook ti’, u beetik ts’ook ti’ jump’éel ba\'ax u yantal yéetel u yantal tu ka\'anal.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (9, 10, 'Ok', 'El perro', 'Es la energía del amor incondicional. El Perro representa la fidelidad, la lealtad y el compañerismo, es el guardián de sus seres queridos. En sombra tiene problemas de autoestima, dando siempre demás a quienes no le corresponden y exigiendo en consecuencia. En luz es capaz del máximo altruismo, sabiéndose amar a sí mismo primero, poniendo límites sanos a todo lo que no le haga bien en sus relaciones afectivas y amando sin aprehensión. Tenderá a dedicarse de alguna u otra manera a proyectos sociales, a hacer el bien por la humanidad. En este sentido tendría que tener cuidado con inconscientemente actuar como el salvador de los demás.', 'Kin_9', 'Oc', 'It\'s the energy of unconditional love. The Dog represents loyalty, fidelity, and companionship; it\'s the guardian of loved ones. In shadow, it has self-esteem issues, always giving too much to those who don\'t reciprocate and demanding in return. In light, it\'s capable of utmost altruism, knowing how to love oneself first, setting healthy boundaries with anything that doesn\'t serve its well-being in relationships, and loving without attachment. It tends to dedicate itself in one way or another to social projects, doing good for humanity. In this sense, it should be careful not to unconsciously act as the savior of others.', 'E ri k\'utb\'altzij ri k\'amor ch\'uti\'. Ri Tz\'i\' ri b\'anoj, riqaj laj b\'a\' k\'ut, ri q\'ij, y riqaj laj k\'ut. Rech xk\'utemajol re, chi k\'utal ri winaq chiq\'ui\' chi k\'ulew, chi akajol k\'ut ri winaq ri wach, che\' winaq k\'u\'nimal rech k\'ut. Rech chi wi, k\'utemajol k\'ulew chik, k\'utemajol chik ri k\'amor ri wi k\'ut chik, ri\'aj chi\'ut k\'utab\'äl ri b\'a ri xcha\' ri wi k\'amor ch\'uti\' chi rech taqajol re ri winaq xk\'utik. Q\'eqetaj rech xk\'ulew xkatun re ri\' winaq xewaq. Rech chi wi, q\'eqetaj rech xk\'utijonik chik la q\'ij ulew k\'utb\'altzij chik.', '<span>Ri k’ulik ri b’anob’äl ri k’a’ tzij. Ri Tz’i’ xb’anob’äl ri k’a’ k’ul, ri k’a’ ch’ab’äl yal ri tzijonik, k’o ri k’ajolaj ri nimaj k’o pa ri kik’aslemal. Pa ruk’u’x kik’in kik’in pa ka ri kik’o ri q’aq’alal yal kik’in, xb’anol pa ka kik’in yal kik’in ri k’o yal kik’in ri man kik’o junam yal kik’in, xkojik pa ka ri kik’o ri k’ul ri kik’in. Pa k’o kik’in pa ka xb’ano jun nima’j xajo’ kik’in, xb’anol ri kik’in yal kik’in ri k’o yal kik’in chik, xkojik pa ka kik’in ri k’ulik yal kik’in ri kik’in pa ri kik’in pa ka kik’in ri nimaj k’a’ yal kik’in, xb’anol yal kik’in man xajo’ chik. Xkotzij pa ka kik’in yal kik’in ri kik’otemik chi k’amik pa ri nimaj k’a’ yal kik’in, pa ka xb’ano chi k’a’ yal ri b’anob’äl. Pa ri k’ulik kik’in kik’in pa ka kik’o ri kik’in yal ri kik’in xb’anol k’o ri k’aslemal pa ka ri kik’o.</span>
', 'Es u kuxtalil u k’áatal jump’éel bix u yantal u ya’abachil. U Peek’ u yantal u ka’analil, u nojochil yéetel u ts’ookil kaajil, es u chúumukil ti’ u máako’ob u yilak u k’a’abachil. Ti’ le k’iin ka’analil u yáaxalil tu tsikbalililil ka’anal, u beetik yaan jump’éel ba’ax ma’ u yantal ti’ u yóok’ol k’iin yéetel u ts\'ookil ti’ le ba’ax u ts\'ook. Ti’ le k’iin ku u béeytal jump’éel ka’ansaj kaambal, u yantal u beetik tu yóok’ol k’iin beyo’ob, u ka’ansaj tu tsikbalil ka’anal ti’ jump’éel ba\'ax ma’ u ts’aabal u beetik yéetel u yaantal ts’ook ti’ u yóok’ol k’iin yéetel ts’ook ti’ u yóok’ol k’iin. U k’áat u yantal jump’éel beetil tu ka’anal yéetel le k’iino’obil kaambalil, u beetik le k’áatil tu kaambalil tu kuxtal. Tu le ba’axil u ts\'o\'ok u k\'áat yéetel jump’éel k\'iin tu yilajil u yantal beyo\'ob u nojoch u ts\'ookil ti\' u yóok\'ol kaajo\'ob.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (10, 11, 'Chuwen', 'El mono', 'Es el niño interior que con su sabiduría ilumina la vida de los demás. En luz es el sentido del humor, lo lúdico, la irreverencia que cuestiona todo como jugando. En sombra suele tender a tomarse todo demasiado en serio y actuar como el abogado defensor de las causas justas. No se permite relajarse y guarda situaciones de la infancia por resolver. Su misión será mostrarle al mundo que nada es tan sólido como parece y que a veces es necesario confrontarnos desde la risa para lograr soltar el ego.', 'Kin_10', 'Chuen', 'It\'s the inner child who, with its wisdom, illuminates the lives of others. In light, it\'s the sense of humor, the playful spirit, the irreverence that questions everything as if playing. In shadow, it tends to take everything too seriously and act as the defender of just causes. It doesn\'t allow itself to relax and holds onto unresolved childhood situations. Its mission will be to show the world that nothing is as solid as it seems and that sometimes it\'s necessary to confront ourselves through laughter to let go of the ego.', 'E ri\' q\'ij b\'i k\'ut rech chi k\'utemajol chik la ri b\'anoj xchiq\'ui\'. Rech chi wi, k\'utemajol rech k\'ut la yala\' ri chik, la awa\'l, la chwäch\' k\'ut xch\'upk\'ij ri b\'i chi rech chwäch\'oj chik. Rech chi winaq taqi\', k\'utemajol xk\'utk\'uch ri b\'i ri xcha\' chiq\'ui\' la xch\'utk\'uch. Rech chi b\'anoj chi\' wi, chi b\'i\' taq k\'ut q\'eqetaj k\'ut la wachaj chi\'ut chik y chi winaq la winaq chiq\'ui\' chi awa\'l. Ri\'aj chi chik chik chik k\'ut rech k\'utemajol chik ulew xchiq\'ui\' ulew chik ri b\'i xcha\' ulew.', '<span>Ri nim q’ij ri k’aslemal ri kik’aslemal chi k’amik ri k’ulik ri nimaj k’o. Pa k’o ri k’ulik ri xajo’ k’ul, ri nimanel ri tijob’äl, ri k’ulik ri man kikotem yal kik’o chi k’amik ri tzij. Pa ruk’u’x kik’in xb’anol chi k’amik pa kik’in yal kik’in, xkojik pa ka ri kik’in ri ruwi’ yal kik’in ri b’anob’äl chi k’amik ri nimaj k’a’ yal kik’in. Man xkib’anol chi k’amik yal kik’in ri nimanel ri kik’in pa ri nimaj tzij. Ri xb’an kik’in ri kik’o yal kik’in chi k’amik ri nimanel pa ka ri kik’in ri nimaj k’a’ man xajo’ chik ri ja’ yal kik’in k’o, yal ri kik’in pa ka ri kik’in ri kik’otem ri tukel chi k’amik pa ka ri kik’o ri q’aq’al k’ul pa kik’o kik’in ri k’aslemal.</span>
', 'Es u ts’o’ok ti’ u máak’ab tu yóok’ol k’iin u yantal u yáaxil tu kuxtalil u máako’ob. Ti’ le k’iin ku es u tsikbalil tu tsikbal, u k’aay, u najil u beetik tu yaantal u yóok’ol kaajil bey jump’éel k’iin. Ti’ le k’iin ka’analil u ts\'o\'oksaj tu yaantal u tsikbal u tsikbal tu yaakuntik yéetel u yantal u beetik jump’éel abogado tu beetil le k’iino’ob ka’ansaj. Ma’ u yantal u chokoj yéetel u yaantal tu tsikbalil ti’ u máak’ab ti’ u tsikbal. U ts’ook u yantal u yóok’ol k’iin bey jump’éel ba’ax ma’ tu yilaj jump’éel tu chichan yéetel u ts’o’oksaj u beetik ti’ u yilaj tu tsikbal ti’ le k’áatal ti’ u yaantal u chi’ u ts\'ook.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (11, 12, 'Eb\'', 'El humano', 'Representa el más alto estándar de integridad. Es el sabio que defiende las causas justas, habitualmente sacrificándose en el proceso. En luz está en conexión profunda con su libertad y sabrá equilibrar su gran necesidad de generar armonía alrededor suyo con el camino que quiera elegir. En sombra, se pospondrá por el resto o caerá en la indecisión aguda de no saber qué decisiones tomar, por tener un concepto rígido del deber ser.', 'Kin_11', 'Eb', 'It represents the highest standard of integrity. It\'s the wise one who defends just causes, often sacrificing themselves in the process. In light, they are deeply connected to their freedom and will know how to balance their strong need to generate harmony around them with the path they choose to take. In shadow, they may defer to others or fall into acute indecision, not knowing which decisions to make, due to having a rigid concept of what should be.', 'Rech taq k\'ut k\'utb\'alaj chik taq awal rech chi q\'eqemajal b\'i\'. Rech chi winaq k\'utemajol rech chi k\'o\'j wi, xecha\' chi b\'anoj chik b\'i chik, k\'ut qach\'ab\' chik rech chi b\'i. Rech chi wi, taqi\' rech b\'i\' xk\'utk\'uch k\'ut wi k\'utemajol chik k\'u rech winaq chik xk\'utk\'uch ulew chi\'ut chik rech k\'utemajol chik b\'i ri\'. Rech chi b\'anoj, rech qach\'ab\' k\'u xkib\'äl rech b\'i k\'u rech xk\'utb\'äl ajinaj rech chi k\'utemajol b\'i\', b\'i\' ri k\'ut taq xkib\'äl k\'u chi k\'u\'x chi rech k\'utemajol k\'ut chi.', '<span>Xb’anob’äl ri nima’j nimaj k’ulik ri kik’aslemal. K’o ri ajq’ij xb’anob’äl ri nimaj k’a’ yal kik’in, xaq k’o ch’ab’äl ri nimaj ri kik’in pa ri k’o. Pa k’o ri k’ulik ri kik’o pa jun nima’j xajo’ yal kik’in ri kik’ul yal kik’in yal kik’o ri kik’in pa ka ri kik’in ri k’ulik ri tzijonemil xajo’ ri k’o ri kik’in yal kik’in chik. Pa ruk’u’x kik’in, kik’in ri kik’o pa ka kik’in ri kik’aslemal o kik’in ri kik’in pa ka kik’o ri junam ri kik’in pa ka kik’in ri nimaj tzijonemil, rumal kik’in ri kik’in ri nimaj k’a’ yal kik’in chi k’o.</span>
', 'U yantal le najilil u chi\'ibal kuxtal. Es u nojoch u ts\'aabal u k\'iino\'obil ka\'ansajil, ti\' jump\'éel tu yo\'osal ku yaantal u ya\'abachil ti\' le k\'iinil. Ti\' le k\'áanalil ku yaantal jump\'éel nojoch u yantal ti\' u yóok\'ol k\'iin yéetel u k\'áatal u yantal u ts\'ookil u kuxtal u yáaxal u yantal u tsikbal tu yóok\'ol k\'áak\'nal ti\' jump\'éel ba\'ax u ts\'aabal u beetik. Ti\' le k\'áanalil ku ts\'ookik tu yóok\'ol yéetel ku yaantal u béeytal u ma\'alobil ti\' u yilaj u béeytal u yaantalil u beetikil, bey ma\' u ts\'ookik u k\'áatil tu yilaj jump\'éel tu yilaje\'ex chichan tu beetike\'ex.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (12, 13, 'B\'en', 'El caminante del cielo', 'Es el explorador, el buscador del sentido último de la existencia. Su principal motivación es conocer, conocerlo todo, sobre todo otras culturas, otros territorios, otros saberes, otras idiosincrasias. En luz, sabrá dejarse guiar por su intuición y todo lo que conozca logrará transformarlo, para luego compartirlo con el mundo. En sombra, el escepticismo le jugará malas pasadas, y solo buscará que conocer hacia fuera, sin tener el coraje de viajar dentro suyo ni de encontrar un camino espiritual.', 'Kin_12', 'Ben', 'It\'s the explorer, the seeker of life\'s ultimate meaning. Their main motivation is to know, to know everything, especially about other cultures, territories, knowledge, and idiosyncrasies. In the light, they will know how to be guided by their intuition, and everything they learn will be transformed, to then be shared with the world. In the shadow, skepticism will lead them astray, and they will only seek to know outwardly, lacking the courage to journey within themselves or to find a spiritual path.', 'Rech chi k\'ajolaj, rech chi q\'eqemajol ri b\'i\' chik wi k\'ut rech ri b\'i\' ri\'. Ruk\'u\'x k\'ut b\'i\' k\'ajolaj wi k\'ut, k\'ajolaj chik taq b\'i\' k\'u rech k\'utemajol, k\'u xkib\'äl, k\'u xk\'ajolaj, chik k\'u xk\'utemajol ri b\'i\'. Rech chi wi, taqi\' k\'utemajol rech chi\'uk\' ri k\'ut k\'ut k\'u wi k\'ut, chik taq k\'ut xkib\'äl b\'i\' k\'u k\'u xkib\'äl, b\'i\' ri rech k\'utemajol ri chik. Rech chi b\'anoj, rech b\'i\' qach\'ab\' k\'u rech xkib\'äl ajinaj k\'ut ri b\'i\' chik wi k\'ut chik, xewitzel k\'u ri k\'utemajol b\'i\' chik wi k\'ut chi b\'anoj.', '<span>Ri nimanel pa ri k’ulik, ri k’otemaj pa ka xb’ano ri nimaj tzij pa ri k’aslemal. Ri k’ulik ri kik’in yal kik’in chi k’amik pa kik’in ri kik’in, kik’in ri kik’in, xaq junam ri nimaj qach’ab’äl, ri nimaj ya’ yal kik’in, ri nimaj ruwi’ yal kik’in, ri nimaj qach’ab’äl chi k’amik. Pa k’o ri k’ulik kik’in ri kik’o yal kik’in pa ka xb’anol yal kik’in ri kik’in pa ka ri kik’in yal kik’in chi k’amik, yal kik’o chi k’amik ri kik’in yal kik’in pa k’ul k’o yal kik’in. Pa ruk’u’x kik’in, ri k’aslemal chi k’amik kik’in ri kik’o junam ri kik’in yal kik’in chi k’amik ri kik’in, yal kik’in kik’in pa ka kik’in ri kik’in chi k’amik pa k’ul k’o yal kik’in, man xb’anob’äl chi k’amik ri kik’in pa kik’in ri kik’in chi k’amik yal kik’in ruwi’ yal ri kik’in k’ul.</span>
', 'Es u máax u tsikbalil, u yaantal u kuxtalil u yáaxil tu ka’analil kuxtal. U nojoch u ts\'ookil u k\'áatal u yantal, u yantal jump\'éel ba\'ax, bey xan jump’éel tu tsikbalo\'ob tu yaanal, tu ka’ano\'ob, tu tsikbalo\'ob, tu ya\'abalo\'ob. Ti\' le k\'áanalil u béeytal u yaantal ti\' u chi’ibalil yéetel jump’éel ba\'ax u yantal u béeytal u ts\'aabal u k\'áatal, ti\' jump\'éel k\'iin u béeytal u yantal ti\' le k’iin. Ti\' le k\'áanalil, u kuxtal u k\'a\'atal jump\'éel chi’ibalil ya\'abachil, yéetel jump\'éel u yaantal u k\'áatal ti\' jump\'éel, ma\' u ts\'ookik u k\'áatil u tsikbalil ti\' u yóok\'ol k\'iin ni\' u yantal u tsikbalililil ti\' u yantal u ts\'ook.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (13, 14, 'Ix', 'El mago', 'Es el que con su encanto natural logra transformarlo todo. Artista, performer, alquimista, sanador, brujo, ingeniero, consejero, orador. En luz, podrá cumplir con su misión de ser fuente de inspiración para los seres humanos, en sombra la soberbia lo llevará a preocuparse solo por la valoración externa, por los aplausos.', 'Kin_13', 'Ix', 'It\'s the one who, with their natural charm, manages to transform everything. Artist, performer, alchemist, healer, wizard, engineer, counselor, speaker. In the light, they can fulfill their mission of being a source of inspiration for human beings; in the shadow, pride will lead them to worry only about external validation, about applause.', 'Rech ri k\'ut ri\' k\'utemajol rech ri ri\' ta k\'u xk\'utemajol ri b\'i\' chik. Ri\'atz\'ib\'al, ri\'malaj, ri\'k\'utnäch, ri\'xk\'ajolaj, ri\'maj b\'i\', ri\'winaq, ri\'tz\'utuj, ri\'jak\'aq. Rech chi wi, chi k\'u\'xk\'utemajol ri rech b\'i\' ta k\'u ri k\'ut ri\' k\'u\'xk\'utemajol ri winaq, chik taq chi\'uk\' chik wi k\'u k\'u k\'ut b\'i\' k\'u b\'anoj.', '<span>Ri xkojik ri k’ulik ri k’aslemal yal kik’in ri nimanel chi k’amik ri nimaj. Ri ajq’ij, ri q’ijob’äl, ri k’ulchi’ k’ul, ri k’ulik yal kik’in ri b’anob’äl, ri k’aslemal, ri k’ulchi’ k’ul, ri q’aq’alal, ri xb’anob’äl. Pa k’o ri k’ulik kik’in ri kik’o yal kik’in pa kik’in ri kik’o junam ri k’ul pa ka xb’ano yal kik’in ri nimaj k’o, pa ruk’u’x kik’in ri q’aq’al kik’in ri kik’o junam ri kik’in yal kik’in chi k’amik ri kik’in pa k’ul kik’in ri b’anol yal kik’in, ri nimaj xajo’ chi k’amik.</span>
', 'Es u ts\'ookil u yantal u k\'uxubil najil u béeytal u ts\'aabal jump\'éel ba\'ax. Artista, performer, alquimista, ts\'akab, x\'men, k\'áak\'naab, nojoch k\'aayil, orador. Ti\' le k\'áanalil, u béeytal u yaantal u ts\'ook u yantal u yáaxal u yantal u yilaj tu máako\'ob tu kuxtal, ti\' le k\'áanalil u ka\'anal u yantal tu yilaj jump\'éel tu yaanal u beetik yéetel u yaantal ti\' le k’iino\'ob.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (14, 15, 'Men', 'El aguila', 'Representa la visión panorámica, la agudeza analítica y la creatividad de vanguardia. Es visionaria y muy profunda, sintiéndose siempre responsable del bienestar ajeno. En luz logrará creer en sí misma para emprender el vuelo y evolucionar, en sombra se quedará procastinando distrayéndose con todo lo que su mente es capaz de vislumbrar, y poniendo el bien común adelante de sus prioridades como pretexto.', 'Kin_14', 'Men', 'It represents the panoramic vision, analytical acumen, and cutting-edge creativity. It\'s visionary and very profound, always feeling responsible for the well-being of others. In the light, she will believe in herself to take flight and evolve; in shadow, she will procrastinate, distracting herself with everything her mind can envision, and putting the common good ahead of her priorities as a pretext.', 'Rech ri xk\'otik ri\'chiq\'aj, ri\'wak\'ib\' ri\'wi\' ri\'k\'utemajol ri b\'i\' chik. Ri\'k\'otikaj wi, chiri ch\'umil, chi winaq chik k\'u ri q\'ij k\'ot xk\'otikaj, chik ri\' ch\'umil rech chik chi k\'utemajol ri b\'i\' rech winaq, chik taq ri\' k\'u ri\' xk\'otikaj, chi rech b\'i\' rech ri\'wi\', chik k\'ajol ri\'xk\'utemajol ri k\'i k\'ut ri\' yinak.', '<span>Xb’anob’äl ri xajo’ k’ul pa ri nimanel, ri xajo’ chi k’amik yal kik’in yal ri k’otemab’äl chi q’ij. K’o jun ch’ab’äl yal kik’in, xb’anol pa ka kik’in ri kik’ul yal kik’in, kik’in pa ka kik’in ri kik’ul yal kik’in ri b’anob’äl chi k’amik. Pa k’o ri k’ulik kik’in ri kik’o yal kik’in pa kik’in kik’in pa ka kik’o ri kik’in yal kik’in kik’otemik, pa ruk’u’x kik’in kik’in pa ka kik’in ri kik’in ri kik’o chi k’amik ri kik’in yal kik’in kik’o pa ri nimaj k’a’ yal kik’in, yal kik’in ri kik’o chi k’amik ri b’anob’äl k’ul pa ri nimaj ri kik’in pa ka ri nimaj k’a’ chi k’amik.</span>
', 'U yantal le ts’ookbilil xíimbal, le chi’ibalil analítico yéetel le chi’ibalil tu yóok’ol kaajil. Es u ts’ookbilil yéetel jump’éel najil tu tsikbal, u yantal jump’éel ba’ax u yantal u k’iino’obil ti’ u tsikbalil le kaajo’ob. Ti’ le k’áanalil u ts’o’okol u yantal ti’ u yóok’ol k’iin u béeytal u béetbilil yéetel u tsikbalil, ti’ le k’áanalil u béeytal u tsikbal u ts’áabal ti’ jump’éel k’iin yéetel jump’éel ba’ax u tsikbalil yéetel u yantal ti’ jump’éel u tsikbalil tu ka’anal, yéetel u yantal le kuxtalil kaajil tu chik’ul ti’ u yaantal tu tsikbalo’ob bey jump’éel tsikbal.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (15, 16, 'Kib\'', 'El guerrero', 'Es el samurai, el que con disciplina y entrega se entrena para ir a la batalla a ganar. Pero la batalla no es el conflicto, es la posibilidad de transformar la realidad, aquello que es injusto, de manera estratégica, intrépida, frontal y sobre todo humilde. Un Guerrero en sombra lo cuestiona todo solo por ego, incluso a sí mismo, autoboicoteándose. En luz es el maestro espiritual, perfil bajo, que ilumina con sus acciones.', 'Kin_15', 'Cib', 'He is the samurai, who with discipline and dedication trains himself to go into battle to win. But the battle is not the conflict; it is the possibility of transforming reality, that which is unjust, in a strategic, fearless, frontal, and above all humble manner. A Warrior in shadow questions everything only out of ego, even himself, sabotaging himself. In the light, he is the spiritual master, low-profile, who illuminates with his actions.', 'Ri\'k\'iche\' k\'ot, ri\' re k\'ot samurai, chi ch\'ajij k\'u ri tijonel chik taq ri k\'otol, k\'u chiri k\'otol, k\'u b\'i\' ri xk\'otol rech k\'u ri k\'otol, b\'i\' ri k\'otol k\'u chi xk\'otol xk\'utinaj, xk\'ulew, xa k\'i\'wi\', xa k\'i\'ikaj k\'ab\'ajel ri k\'u\' rech k\'u xk\'utinaj. Ti rej k\'otol ri\'xk\'utinaj chiri k\'ot, ti ch\'ab\'ab\' k\'u ri k\'ot, xk\'utinaj k\'u k\'i\', xk\'utinaj k\'u aj ch\'utemajal, k\'u aj k\'ajol k\'u tijonel chik.', '<span>Ri samurai, ri k’o pa k’ulik yal kik’in ri nimanel chi k’amik ri kik’otemik pa ka ri k’ul chi k’amik. Xaq ri k’ul man xb’ano ri tzij, xb’ano ri nimanel pa ka xb’ano ri nimanel chi k’amik, ri ja’ chi k’amik, pa jun nima’j nimaj k’ul, xajo’ k’ul, xajo’ chi k’amik yal ruwi’ yal kik’in k’a’. Jun Ajchajil pa ruk’u’x kik’in xb’anol chi k’amik junam ri tzij ri kik’in yal kik’in chi k’amik, xaq xb’anol ri kik’in yal kik’in, xb’anolik chi kik’in. Pa k’o ri k’ulik kik’in ri k’o jun nima’j ajq’ij k’aslemal, xajo’ ruwi’ chi k’amik, xb’anob’äl pa kik’in ri nimaj k’o chi kik’in yal kik’in.</span>
', 'Es u samurai, le máak’ ku beetik tu ka’anal yéetel u ts’ook ti’ k’áat u xook ti’ jump’éel k’iin ku ya’abil. Ba\'ale\' le k’iin ma’ u ts\'ook, es le ku ka’analil u ts’aabal u ka’anal, le ba\'axil ku k\'a\'atal u yáaxil tu tsikbal, le ba\'ax ma\' u nojoch, ti’ u chi\'ibalil, u k’a’analil, yéetel jump’éel ch’aak’ yéetel u yantaj tu ka\'anal. Jump’éel B’a’alam tu k’iin ma’ ts’aabal u tsikbalil le ku ya’abil tu yóok’ol u kuxtal, ti’ jump’éel ego, beyo’ xan ti’ u bey, ku ya’anal u yaabil tu tsikbalil. Ti’ le k’áanalil es u nojoch k’aay, najil, le máak’ ku yáantal tu ya’abil yéetel u ts’ook ti’ jump’éel le ba\'ax ku beetik.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (16, 17, 'Kab\'an', 'La tierra', 'Representa la estabilidad suprema. Es la dadora de base, de estructura, tanto en el plano físico como en el emocional, psíquico o espiritual. Suelen ser personas bastante fuertes que logran impulsar, con su gran empuje, a que se genere aquello que hace falta para salir adelante. En sombra caen en la sobre interpretación, en ser retadoras, creando argumentos solo para validar aquello con lo que se han entercado. En luz, saben que la verdadera estabilidad es fluir con lo que la realidad les propone, sin presionar, sin recurrir a la fuerza.', 'Kin_16', 'Caban', 'She represents supreme stability. She is the giver of foundation, of structure, both in the physical and in the emotional, psychic, or spiritual plane. They tend to be quite strong individuals who manage to propel, with their great drive, the generation of what is needed to move forward. In shadow, they fall into over-interpretation, being challengers, creating arguments only to validate what they have set their minds on. In light, they know that true stability is to flow with what reality proposes, without pressuring, without resorting to force.', 'Ri rutz\'ij ri e wach chiwäch. Chi ri taqawäch, ri wuj, xk\'utinaj ri wäch, ki\' rej k\'a ri tzukub\'aj chi k\'otol chik ri k\'otol wi, xk\'utinaj ki\' rej k\'a ri tak\' k\'u k\'otol, ri uq\'ijil, utz\'ijil, k\'u k\'otol k\'ajol k\'u wuj. Ti chiri\' xk\'utinaj, chi k\'otol wuj, chiri ta chik k\'ajolaj k\'u rech, ta k\'u ch\'ok ri k\'otol rech, xk\'utinaj ujol wi\' chi wakax ri k\'u ch\'ok. Ti wi\' chiri, chi ri k\'otol xk\'utinaj k\'u q\'eqi\', k\'u ri k\'otol tzukub\'aj rech wi\', ta\' wi\' k\'a\' ri k\'i\' ri k\'otol k\'u wach, k\'u utz\'ijil.', '<span>Xb’anob’äl ri nimaj tzijonemil ruwi’. K’o ri k’ulik yal kik’in ri k’o pa ri nimanel, pa ri ruwi’ yal kik’in, xaq junam ri k’aslemal yal kik’in, ri k’aslemal chi k’amik yal kik’in o ri k’aslemal k’ul. Xb’an pa ka kik’o ri kik’in yal kik’in chi ruwi’ yal kik’in chi k’amik, kik’otemik pa ka kik’in ri kik’in chi k’amik ri kik’in yal kik’in kik’o. Pa ruk’u’x kik’in, kik’in ri kik’in pa ka kik’in ri kik’in ri kik’in chi k’amik, xb’anol chi k’amik, xb’anol ri tzij yal kik’in kik’in ri kik’in pa ka kik’in ri nimaj ri kik’in yal kik’in. Pa k’o ri k’ulik kik’in kik’in ri kik’in chi k’amik ri nimaj tzijonemil k’ul xb’anol pa ka kik’in ri nimaj ri kik’in yal kik’in pa kik’in, man xajo’ chi k’amik, man xb’anol yal kik’in chi k’amik.</span>
', 'U yantal le nojoch ts\'o\'okil. Es u beelil u nojoch k\'iin, le estructura, tu yáaxil tu k’iin, ti’ u yóok’ol kuxtal yéetel tu yóok’ol yóok\'oltik, tu yóok’ol k’iin yéetel tu ka’anal. Ku ya’abil jump’éel máako’ob ku ts’ook u kuxtalil, ku yáantaj tu ts\'ookil, u k’a’atal u ya’abil le ba’ax ku k’a’atal u kuxtal. Ti’ le k’áanalil u yantal tu ya’abilil u beetik, ti’ u k’áatal u beeytil u ts\'ook tu ya’abil le ba’ax u ts\'ook. Ti’ le k’áanalil, ku ya’abil u nojoch k’aay, u ka’analil ku yáantaj tu k\'iin yéetel u ts\'ook le ba’ax ku ya’abil, ma\' ts\'ook, ma\' ku ya’abil u ya’abilil. Ti’ le k’áanalil ku ya’abil ku ka’anal tu kuxtal, ku ts\'ook yéetel le ba’ax ku ya’abil, ma\' ku ya’abil u ya’abil.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (17, 18, 'Etz\'anab\'', 'El espejo', 'Es el equilibrio perfecto, la ecuanimidad, la paz interior que brota gracias a una verdadera aceptación de todo tal y como es. En luz el Espejo fluye con todo sin filtros ni reparos, generando una gran armonía entre quienes lo rodean. Es uno de los sellos que se suele llevar mejor con la gente. En sombra sin embargo tiende al juicio extremo, no encuentra orden nada, menos en sí mismo, y termina en crisis por criticarlo todo. No es capaz de verse y suele proyectar sus defectos en los demás. En el calendario maya tradicional se le asocia al cuchillo de obsidiana, cualidad espiritual para cortar de raíz con todo lo que no nos sirve en nuestra vida', 'Kin_17', 'Etznab', 'It is the perfect balance, the equanimity, the inner peace that arises thanks to a true acceptance of everything as it is. In light, the Mirror flows with everything without filters or reservations, generating great harmony among those around it. It is one of the seals that usually gets along well with people. In shadow, however, it tends towards extreme judgment, finding no order in anything, least of all in itself, and ends up in crisis by criticizing everything. It is not capable of seeing itself and tends to project its defects onto others. In the traditional Maya calendar, it is associated with the obsidian knife, a spiritual quality to cut off everything that does not serve us in our lives.', 'Ri b\'anojil wi\', ri k\'akajay, ri wäch k\'i\' ri kajib\' wi\' xk\'utinaj ta ch\'ut ri xk\'ot ri wuj chik ri k\'otol k\'u q\'eqi\' rech. Ti wi\' ri k\'u q\'eqi\' ta\' xk\'utinaj ri Xb\'alamuk\' wi\' chi wach wuj wi\' rech ri\' k\'u q\'eqi\' rech xk\'utinaj utz\'ijilaj k\'u utz\'ijil rech chik ri k\'otol k\'u chik. Ta k\'u wach uwi\' rech xk\'utinaj k\'u k\'i\' ri k\'otol k\'u wach. Ta\' ri k\'otol uqijil chik ri k\'u q\'eqi\' rech k\'u utz\'ijilaj k\'u k\'i\' ri k\'otol k\'u wach, chik ri q\'eqi\' rech. Ta\' ri wuj k\'u k\'otol maya k\'i\' xk\'utinaj uch\'ab\'al xk\'ajolol, ki ri\' q\'eqi\' rech ta\' utz\'ijilaj k\'u wuj chik ri wach k\'u k\'otol rech', '<span>Ri k’ulik ri nimaj k’ul, ri nimaj k’a’ ch’ab’äl, ri nimaj k’a’ k’ul pa ri k’aslemal xb’anol pa ka kik’in ri nimaj k’a’ chi k’amik ri ja’ yal ri kik’in. Pa k’o ri k’ulik ri Tz’aqal xb’anol yal kik’in ri nimaj yal kik’in man xajo’ chi k’amik yal kik’in, xb’anolik ri nimaj ch’ab’äl chi k’amik pa ri kik’in yal kik’in kik’in ri kik’in chi k’amik. K’o junam ri b’ix yal kik’in xb’ano chi k’amik yal kik’in chi kik’in. Pa ruk’u’x kik’in, xaq kik’in ri kik’in xb’anol chi k’amik yal kik’in, man kik’o ri k’ul pa ka ri kik’in ri nimaj, xaq pa ri kik’in chi k’amik, yal kik’in pa ka ri kik’in yal kik’in xb’anol ri nimaj ri kik’in yal kik’in. Man xb’ano chi k’amik pa kik’in yal kik’in chi k’amik yal kik’in xb’anol ri q’aq’al yal kik’in pa ri kik’in. Pa ri ruwi’ ri k’aslemal Q’ij xb’anob’äl ri k’ulik ri q’aq’al chi k’amik pa ka kik’in ri nimaj k’a’ pa ka ri kik’in ri man kik’in yal kik’in ri nimaj chi k’amik.</span>
', 'Es u ts’ookilil perfecto, u nojoch yéetel u nojoch ts’ookilil, le ka’analil ti’ yóok’ol k’iin u yáantaj tu ts\'ookilil le ba’axil yéetel u ts’a’abal. Ti’ le k’iin ku, le Lool ku ts’ook yéetel jump’éel ba’ax ma’ u yilaj yéetel ma’ ku yáantaj, u yáantaj tu nojoch k’iin ti’ le máako’ob ku ya’abil. Es jump’éel le ba’ax ku ya’abil u k’iinil máako’ob yéetel le máako’ob. Ti’ le k’iin ka’analil ku ya’abil u nojoch k’iinil, ma’ ku ya’abil u k’iin yéetel jump’éel, ku ya’abil u ya’abilil ti’ u k’a’analil, ma’ ku ya’abil u kuxtal yéetel ku ya’abil tu ya’abilil tu beetik u yáantal u nojoch yáaxil ti’ jump’éel. Ma’ ku ya’abil u ya’abil yéetel ku ya’abil u nojoch máako’ob tu kaambalil. Ti’ le k’iin ti’ jump’éel k’iin maya tradicional ku ya’abil u ts’ookilil u chi’ibalil, u nojoch yaabilil ka’analil ku ya’abil tu kaanal jump’éel ba’ax ku ya’abil tu kuxtal.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (18, 19, 'Kawak', 'La tormenta', 'Es la fuerza transformadora de la realidad. Cuando aparece la tormenta es momento de cambios radicales, no hay de otra. En general es una energía poderosa de creación, suele pasar perfil bajo pero cuando llega el momento se manifiesta con una gran fiereza. En sombra se estacan y no se permiten cambiar, o al revés, generan cierta adicción a los movimientos fuertes permanentes. Pueden también quedarse en la extrema introspección, son muy sensibles, y no mostrarse. En luz logran generar situaciones límites para dejar ir aquello que ya le tocaba irse y poder volver a empezar en un nuevo nivel de evolución.', 'Kin_18', 'Cauac', 'It\'s the transformative force of reality. When the storm appears, it\'s time for radical changes, there\'s no other way. In general, it\'s a powerful creative energy, it tends to keep a low profile, but when the time comes, it manifests with great fierceness. In shadow, they stagnate and don\'t allow themselves to change, or conversely, they develop a certain addiction to constant strong movements. They can also remain in extreme introspection, they are very sensitive, and they don\'t show themselves. In light, they manage to create boundary situations to let go of what needed to go and start again at a new level of evolution', 'E ri k\'anal ch\'ut ch\'oy. Rech xk\'atun ri tempestad, chi wi xk\'ot xchinku\' chi k\'u\'j, ma chik xewaq k\'ulew. Xecha wi k\'utb\'altzij q\'ij, chi ajk\'ub\' ri b\'anoj, chik\'a chik\'uxul, ba\'q\'ij xk\'ot xchinku\' chi winaq xk\'ot, che\' chik\'uxul. Rech xk\'ut re ri b\'anoj, k\'atunajol chik, k\'utemajol chik, jok\'ojol k\'utu\'x. Rech chi wi, che\' chik\'ajol ri xtreme k\'umal, ma chik. Ma k\'ulew, chik b\'a ri ki\'che ch\'umil k\'utuj ri chik ri aq\'ab\'äl rech a\' ri aq\'ab\'äl rech a\' chik\'ajol ri wi kib\'äl.', '<span>Ri k’ulik ri xb’ano chi k’amik ri nimanel. Xa ri taq’anom xb’ano, ri kik’in pa ka xb’ano ri nimaj k’a’ chi k’amik, man xb’anol jun ri xajo’ chi k’amik. Xaq pa junam k’o ri nimaj k’ulik yal kik’in ri k’ulik, xb’anol chi k’amik pa ka ri kik’in ri q’aq’al chi k’amik yal kik’in kik’o ri nimaj k’a’ chi k’amik. Pa ruk’u’x kik’in, kik’in ri kik’in xb’anol chi k’amik yal kik’in, man xb’anol pa ka kik’in ri kik’in chi k’amik, o pa ka xb’ano ri nimaj k’a’ pa ka kik’in ri nimaj ri kik’in xb’anol ri nimaj k’a’ yal kik’in chi k’amik. Xaq xb’anol pa ka kik’in ri nimaj ri xajo’ chi k’amik, xb’ano yal kik’in, yal man xb’anol chi k’amik. Pa k’o ri k’ulik kik’in kik’in xb’ano ri nimaj k’a’ chi k’amik pa ka xb’ano ri kik’in pa ka kik’in ri kik’in pa ka kik’in chi k’amik yal kik’in xb’anol chi k’amik pa ri nimaj k’a’ yal kik’in xb’anol yal kik’in.</span>
', 'Es u yáantaj tu kaanalil kuxtal. Tu ka’analil ku ya’abil le k’áankin es jump’éel k’iinil u ts’a’abal ku xíimbal, ma’ yaan jump’éel k’iino’obil. Tu yáax kuxtal ku yáabil u chúumukil u yantal, ku ts’ook u yaantal, ba’ale’ ku ya’abil u nojoch k’iin ti’ jump’éel k’iinil u k’a’ab. Ti’ le k’áanalil, ku ya’abil ku k’a’atal yéetel ma’ ku ya’abil u ts’a’abal, o ku ya’abil jump’éel k’a’ansaj tu kuxtal yéetel ma’ ku ya’abil u ya’abilil. Ku ya’abil xan tu yaanalil kuxtalil, ku yáantaj jump’éel tu yóok’ol k’iin, yéetel ma’ ku ya’abil u ya’abil. Ti’ le k’iin ku ku ya’abil ku k’a’atal yéetel jump’éel tu ts’ookil, u k’áatal ku ts’ook jump’éel ba’ax u yáabil tu ts’a’abal yéetel ku ts’ook ti’ jump’éel u ts’a’abal u yáax k’iinil tu ya’abil.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (19, 20, 'Ajaw', 'El sol', 'Es la energía de mayor evolución. Representa la luz generadora de vida, la sabiduría, la verdad, las cosas tal y como son. Cuando aparece el Sol es momento de brillar, de confiar en quienes ya somos y en lo que ya sabemos de manera intrínseca, y asumir los roles de autoridad, de liderazgo que nos correspondan. Es momento de afrontar la realidad como se presente, así nos cueste. El problema con el Sol es que al ser la verdad puede tornarse intransigente, radical con la ética, con los paradigmas, con lo que considera correcto o cierto, así, debe trabajar por sobre todas las cosas la humildad. La verdadera sabiduría no se anda mostrando, defendiendo o convenciendo, es un estado del alma, de conexión permanente con nuestro ser auténtico.', 'Kin_19', 'Ahau', 'It\'s the energy of higher evolution. It represents the life-generating light, wisdom, truth, things as they are. When the Sun appears, it\'s time to shine, to trust who we already are and what we already know intrinsically, and to assume roles of authority, of leadership that correspond to us. It\'s time to face reality as it presents itself, no matter how challenging it may be. The issue with the Sun is that being the truth, it can become uncompromising, radical with ethics, with paradigms, with what it considers right or true, so humility must be worked on above all else. True wisdom isn\'t about showing off, defending, or convincing; it\'s a state of the soul, a permanent connection with our authentic self.', 'E ri energia k\'anal ch\'ut a\' k\'ulew. Chik ri ruk\'ux k\'utuj, ruk\'ux, k\'utb\'altzij, a\'b\'anel ri kib\'äl che\' ri q\'ij. Rech xk\'atun ri q\'ij, chi wi k\'ab\'ij, chik ri a\' winaq chikaj chi wi a\' kib\'äl rech chi wi a\' kib\'äl, che\' kib\'äl che\' chik\'ajol, chib\'äl chik\'ajol ri xub\'inal. Rech xk\'atun ri realidad chi k\'ot xchinku\' chi k\'u\'j, chi xti\' taq xkoj rech. Ri problema xk\'ut b\'e ri ruk\'ux chi ri q\'ij, chi k\'ulew rech winaq chik ajanel ri k\'u\'xul, k\'u\'xul chi wi, k\'u\'xul che\' a\' che\' b\'anel ri aq\'ab\'äl, ri chik\'ajol ri b\'anoj che\' ri q\'ij ri k\'o ri a\' wi che\' k\'ut. Ri b\'anel ri k\'utb\'altzij ma k\'utuleje\', ma chik\'ajol, ma k\'utwalij, xechawin taq, ri q\'ij rech ajk\'ub\' chikaj ri wi a\' kib\'äl.', '<span>Ri k’ulik ri nimaj k’a’ chi k’amik. Xb’anob’äl ri q’ij xb’ano chi k’amik ri k’aslemal, ri nimaj tzij, ri nimaj k’a’, ri nimaj ja’ yal ri kik’in. Xa ri Q’ij xb’ano, ri kik’in pa ka xb’anolik, pa ka kik’otemik ri kik’in yal kik’in xb’anol yal kik’in ri ja’ yal kik’in pa ri k’ulik, yal xb’ano ri qach’ab’äl yal kik’in, ri k’ulik yal kik’in ri kik’in chi k’amik. Ri kik’in pa ka xb’ano ri nimanel chi k’amik ri ja’, xaq kik’in pa ka kik’in ri kik’in. Ri xaqik’ pa ri Q’ij k’o kik’in ri nimaj k’a’ xb’ano chi k’amik, xb’ano yal kik’in ri nimaj tzij, xb’ano chi k’amik yal ri nimaj tzij, yal ri ja’ xb’anol ri kik’in xb’ano chi k’amik o ri nimaj, xaq, xb’anol pa ka kik’in ri kik’in ri k’ulik yal kik’in. Ri nimaj tzij ri ja’ xb’anol chi k’amik, man xb’ano chi k’amik, xb’anol yal kik’in chi k’amik, k’o jun q’aq’al chi k’amik yal ri k’aslemal, ri xb’anol chi k’amik yal ri nimaj k’a’ yal kik’in ri kik’in chi k’amik.</span>
', 'Es u yáantaj tu nojoch ka’analil. U yantal u k’iin generadora kuxtal, le ts’ookbilil, le yáanal, le ba’axil jump’éel k’a’at. Tu k’iin ku ya’abil le K’iin es k’iinil u jáas, u k’a’atal ti’ u ya’abil yéetel le ba’ax ku ya’abil u ya’abil tu yóok’ol kaajil, yéetel u ts’ookil ti’ u ya’abilil. Es k’iinil u xok k’a’anal, u k’a’atal ku ts’a’abal ti’ jump’éel ba’ax ku ya’abil, bey xan ku ya’abil jump’éel bejo’ob yéetel le ku ya’abil u ya’abilil ti’ u kaambal. Le nojoch k’iin le K’iin es ku yáantaj ti’ jump’éel, ku ya’abil ku ya’abilil tu kuxtal, ku yantal u ya’abilil u k’iin yéetel le ba’ax ku k’a’atal ku ya’abil. Bey xan, le nojoch k’iin le K’iin ku k’a’atal u ya’abilil, ku ya’abil ku k’a’atal u ya’abilil yéetel le ts’ookbilil, yéetel le ba’ax ku ya’abil u k’a’atal ku ya’abil. Le nojoch ts’ookbilil ma’ ku ya’abilil tu tsikbal, ma’ ku ya’abilil, ma’ ku ya’abilil ti’ le yáanal, es jump’éel k’iinil u yóok’ol kuxtal, u nojoch k’a’analil yéetel le ts’ookbilil tu kuxtal.
');
